// 1. Obtener la salida de Manager Agent de forma robusta
const primerItem = $input.all()?.[0]?.json || $input.item?.json || {};
let narrativaLLM = primerItem.output || primerItem.text || primerItem.content || '';

if (typeof narrativaLLM === 'object') {
  narrativaLLM = JSON.stringify(narrativaLLM);
}

narrativaLLM = String(narrativaLLM)
  .replace(/```json[\s\S]*?```/g, '')
  .replace(/```[\s\S]*?```/g, '');

// 2. Localizar datos del Subflujo de Metricas o del nodo Normalizar
let datosMetricas = {};
try { datosMetricas = $("Call 'Subflow - Calculo Metricas'").first().json || {}; } catch (e) {}
if (!datosMetricas.calculo_metricas && !datosMetricas.motor_analitico) {
  try { datosMetricas = $('Normalizar Periodo Actual').first().json || {}; } catch (e) {}
}

const motorAnalitico = datosMetricas.calculo_metricas 
  || datosMetricas.motor_analitico 
  || {};

const serieDiaria = motorAnalitico.diario || [];
const totalPeriodo = motorAnalitico.total || {};
const contextoExterno = totalPeriodo.contexto_externo || {};

// 3. Localizar hotelConfig
let hotelConfig = datosMetricas.hotelConfig || {};
if (!hotelConfig.nombre) {
  try { hotelConfig = $('Schedule Trigger Data').first().json?.hotelConfig || {}; } catch (e) {}
}
if (!hotelConfig.nombre) {
  try { hotelConfig = $('Nodo Agregador').first().json?.hotelConfig || {}; } catch (e) {}
}

// 4. Competencia
const competencia = totalPeriodo.competencia 
  || datosMetricas.competenciaResumen 
  || $('Nodo Agregador').first()?.json?.competenciaResumen 
  || {};

const tablaCompetencia = (competencia.hoteles || []).map(h => ({
  nombre: h.nombre,
  rating: h.rating,
  resenas: h.numResenas,
  precio: h.precio
}));

// 5. Estadisticas de ocupacion
const umbralCriticoCfg = hotelConfig.tablas_pricing?.reglas_ocupacion?.[0]?.max;
const umbralCritico = (umbralCriticoCfg ? umbralCriticoCfg / 100 : 0.40);

let mediaOcupacion = 0;
let maxOcupacion = -1;
let minOcupacion = 999;
let fechaMax = '';
let fechaMin = '';
let sumaOcupaciones = 0;
let ocupacionesArray = [];
let diasBajoUmbral = 0;

if (serieDiaria.length > 0) {
  serieDiaria.forEach(d => {
    const oc = d.ocupacion?.prevista !== undefined 
      ? (d.ocupacion.prevista > 1 ? d.ocupacion.prevista / 100 : d.ocupacion.prevista) 
      : 0;
    sumaOcupaciones += oc;
    ocupacionesArray.push(oc);

    if (oc > maxOcupacion) { maxOcupacion = oc; fechaMax = d.fecha; }
    if (oc < minOcupacion) { minOcupacion = oc; fechaMin = d.fecha; }
    if (oc < umbralCritico) { diasBajoUmbral++; }
  });
  mediaOcupacion = sumaOcupaciones / serieDiaria.length;
}

const varianza = ocupacionesArray.length > 0 
  ? ocupacionesArray.reduce((acc, val) => acc + Math.pow(val - mediaOcupacion, 2), 0) / ocupacionesArray.length 
  : 0;
const desviacionEstandar = Math.sqrt(varianza);

const mitad = Math.floor(serieDiaria.length / 2);
const sem1 = serieDiaria.slice(0, mitad);
const sem2 = serieDiaria.slice(mitad);

const mediaSem1 = sem1.length > 0 ? sem1.reduce((acc, d) => acc + (d.ocupacion?.prevista > 1 ? d.ocupacion.prevista / 100 : d.ocupacion.prevista), 0) / sem1.length : mediaOcupacion;
const mediaSem2 = sem2.length > 0 ? sem2.reduce((acc, d) => acc + (d.ocupacion?.prevista > 1 ? d.ocupacion.prevista / 100 : d.ocupacion.prevista), 0) / sem2.length : mediaOcupacion;
const variacionSemanal = mediaSem2 - mediaSem1;
const tendencia = variacionSemanal > 0.01 ? 'ascendente' : variacionSemanal < -0.01 ? 'descendente' : 'estable';

const estadisticasCalculadas = {
  media: mediaOcupacion,
  maximo: maxOcupacion,
  minimo: minOcupacion,
  fechaMax: fechaMax,
  fechaMin: fechaMin,
  tendencia: tendencia,
  desviacion: desviacionEstandar,
  umbralCritico: umbralCritico,
  diasBajoUmbral: diasBajoUmbral,
  mediaSemana1: mediaSem1,
  mediaSemana2: mediaSem2,
  variacionSemanal: variacionSemanal
};

// 6. QuickChart
let chartUrlGenerada = '';
if (serieDiaria.length > 0) {
  const labelsChart = serieDiaria.map(d => (d.fecha || '').slice(5));
  const dataChartPrevista = serieDiaria.map(d => Number((d.ocupacion?.prevista > 1 ? d.ocupacion.prevista : (d.ocupacion?.prevista ?? 0) * 100).toFixed(1)));
  const dataChartActual = serieDiaria.map(d => Number((d.ocupacion?.actual > 1 ? d.ocupacion.actual : (d.ocupacion?.actual ?? 0) * 100).toFixed(1)));
  const dataChartAnioAnterior = serieDiaria.map(d => {
    const v = d.ocupacion?.anio_anterior;
    return (v === null || v === undefined) ? null : Number((v > 1 ? v : v * 100).toFixed(1));
  });

  const chartConfig = {
    type: 'line',
    data: {
      labels: labelsChart,
      datasets: [
        { label: 'Ocupacion Prevista (%)', data: dataChartPrevista, borderColor: '#1e3a8a', backgroundColor: 'rgba(30, 58, 138, 0.1)', fill: true, tension: 0.3 },
        { label: 'Ocupacion Real (%)', data: dataChartActual, borderColor: '#16a34a', backgroundColor: 'rgba(22, 163, 74, 0.05)', fill: false, tension: 0.3 },
        { label: 'Ano anterior (%)', data: dataChartAnioAnterior, borderColor: '#9ca3af', borderDash: [6, 4], fill: false, tension: 0.3, spanGaps: true }
      ]
    },
    options: {
      plugins: { title: { display: true, text: 'Evolucion Demanda: ' + (hotelConfig.nombre || 'Hotel') } },
      scales: { y: { beginAtZero: true, max: 100 } }
    }
  };
  chartUrlGenerada = 'https://quickchart.io/chart?w=650&h=260&c=' + encodeURIComponent(JSON.stringify(chartConfig));
}

// 7. Tabla diaria normalizada
const tablaDiaria = serieDiaria.map(d => {
  const prec = parseFloat(d.contexto_externo?.clima?.precipitacion ?? d.clima?.precipitacion ?? 0);
  return {
    fecha: d.fecha,
    ocupacion_pct: d.ocupacion?.prevista ?? 0,
    ocupacion_actual: d.ocupacion?.actual ?? null,
    adr_eur: d.ingresos?.adr ?? 0,
    adr_sugerido_eur: d.pricing_dinamico?.adr_sugerido ?? null,
    ajuste_pricing_pct: d.pricing_dinamico?.ajuste_pct ?? null,
    revpar_eur: d.ingresos?.revpar ?? 0,
    pickup_7: d.pickup_pace?.pickup_7 ?? null,
    festivo: d.contexto_externo?.es_festivo ? 'Si' : 'No',
    vacaciones: d.contexto_externo?.es_vacaciones_escolares ? 'Si' : 'No',
    lluvia: prec >= 1 ? 'Si' : 'No',
    precipitacion_mm: !isNaN(prec) ? prec : 0,
    temp_max: d.contexto_externo?.clima?.temp_max ?? d.clima?.temp_max ?? null,
    temp_min: d.contexto_externo?.clima?.temp_min ?? d.clima?.temp_min ?? null
  };
});

// 8. Historico
let datosHistorico = {};
try { datosHistorico = $('Calcular Similitud').first().json || {}; } catch (e) {}
const tablaHistorico = (datosHistorico.top3_periodos || []).map(p => ({
  periodo: p.fecha_inicio + ' a ' + p.fecha_fin,
  ocupacion_media: p.ocupacion_media,
  adr: p.adr,
  revpar: p.revpar,
  pickup_7: p.pickup_7,
  pct_festivos: Math.round((p.pct_dias_festivos ?? 0) * 100),
  pct_vacaciones: Math.round((p.pct_dias_vacaciones ?? 0) * 100),
  similitud: p.distancia != null ? Number((1 - p.distancia).toFixed(2)) : null
}));

const ingresosResumen = {
  totales_previstos: totalPeriodo.ingresos?.ingresos_totales_previstos ?? null,
  totales_actuales: totalPeriodo.ingresos?.ingresos_totales_actuales ?? null,
  totales_anio_anterior: totalPeriodo.ingresos?.ingresos_totales_anio_anterior ?? null,
  yoy_pct: totalPeriodo.comparativas?.ingresos_yoy_pct ?? null,
  dias_sin_dato_yoy: contextoExterno.dias_sin_dato_historico_yoy ?? null,
  dias_totales: serieDiaria.length
};

const fechaInicio = serieDiaria[0]?.fecha;
const fechaFin = serieDiaria[serieDiaria.length - 1]?.fecha;
const periodoTexto = (fechaInicio && fechaFin) ? 'Del ' + fechaInicio + ' al ' + fechaFin : 'Proximos dias';

// 9. Resumen cabecero
const ocPrevistaMedia = totalPeriodo.ocupacion?.prevista_media ?? (mediaOcupacion ? (mediaOcupacion * 100).toFixed(1) : 'N/A');
const ocActualMedia = totalPeriodo.ocupacion?.actual_media ?? 'N/A';
const adrMedio = totalPeriodo.ingresos?.adr_medio ?? 'N/A';
const revparMedio = totalPeriodo.ingresos?.revpar_medio ?? 'N/A';
const ingresosTotales = totalPeriodo.ingresos?.ingresos_totales_previstos 
  ? Math.round(totalPeriodo.ingresos.ingresos_totales_previstos).toLocaleString('es-ES') + ' EUR' 
  : 'N/A';
const paceEstado = totalPeriodo.pickup_pace?.estado_pace ?? 'N/A';
const compRating = competencia.ratingMedioZona ?? 'N/A';
const compNum = competencia.numCompetidores ?? (competencia.hoteles?.length || 0);

const cabeceroTexto = 'Resumen Ejecutivo (' + periodoTexto + ') - ' + (hotelConfig.nombre || 'Hotel') + '\n'
  + '* Ocupacion Prevista: ' + ocPrevistaMedia + '% (Actual: ' + ocActualMedia + '%) | Tendencia: ' + tendencia.toUpperCase() + '\n'
  + '* Tarifa Media (ADR): ' + adrMedio + ' EUR | RevPAR: ' + revparMedio + ' EUR | Ingresos Estimados: ' + ingresosTotales + '\n'
  + '* Ritmo (Pace): ' + paceEstado + ' | Compset: ' + compRating + ' estrellas (' + compNum + ' hoteles)';

const cabeceroHtml = '<table style="width:100%; border-collapse:collapse; background-color:#1e3a8a; color:#ffffff; font-family:Arial,sans-serif; border-radius:8px; overflow:hidden; margin-bottom:20px;">'
  + '<tr><td style="padding:18px 22px;">'
  + '<h2 style="margin:0 0 4px 0; font-size:20px; color:#ffffff;">' + (hotelConfig.nombre || 'Hotel') + ' &mdash; Resumen Ejecutivo</h2>'
  + '<p style="margin:0 0 16px 0; font-size:13px; color:#93c5fd;">' + periodoTexto + ' &middot; Horizonte: ' + serieDiaria.length + ' dias</p>'
  + '<table style="width:100%; border-top:1px solid #3b82f6; padding-top:12px; font-size:13px; color:#ffffff; border-collapse:collapse;">'
  + '<tr>'
  + '<td style="padding:6px 4px; width:25%;"><strong>Ocup. Prevista:</strong> ' + ocPrevistaMedia + '%</td>'
  + '<td style="padding:6px 4px; width:25%;"><strong>ADR Medio:</strong> ' + adrMedio + ' EUR</td>'
  + '<td style="padding:6px 4px; width:25%;"><strong>RevPAR:</strong> ' + revparMedio + ' EUR</td>'
  + '<td style="padding:6px 4px; width:25%;"><strong>Ingresos Est.:</strong> ' + ingresosTotales + '</td>'
  + '</tr><tr>'
  + '<td style="padding:6px 4px;"><strong>Tendencia:</strong> ' + tendencia.toUpperCase() + '</td>'
  + '<td style="padding:6px 4px;"><strong>Ritmo (Pace):</strong> ' + paceEstado + '</td>'
  + '<td style="padding:6px 4px;"><strong>Dias Criticos:</strong> ' + diasBajoUmbral + '</td>'
  + '<td style="padding:6px 4px;"><strong>Compset:</strong> ' + compRating + ' &#11088; (' + compNum + ' hoteles)</td>'
  + '</tr></table></td></tr></table>';

return [{
  json: {
    hotelConfig: hotelConfig,
    periodo: periodoTexto,
    cabecero_email_texto: cabeceroTexto,
    cabecero_email_html: cabeceroHtml,
    estadisticas: JSON.stringify(estadisticasCalculadas),
    chart_url: chartUrlGenerada,
    escenario_alternativo: '',
    narrativa_html: narrativaLLM,
    tabla_diaria: JSON.stringify(tablaDiaria),
    tabla_historico: JSON.stringify(tablaHistorico),
    tabla_competencia: JSON.stringify(tablaCompetencia),
    contexto_externo: JSON.stringify(contextoExterno),
    tabla_perfil_demanda: JSON.stringify(totalPeriodo.perfil_demanda || {}),
    ingresos_resumen: JSON.stringify(ingresosResumen)
  }
}];

const actual = $('Normalizar Periodo Actual').first().json.periodo_actual;
const historico = items.map(i => i.json).filter(h => h.fecha_inicio);

const features = ['ocupacion_media', 'adr', 'pickup_7', 'pct_dias_festivos', 'pct_dias_vacaciones', 'pct_dias_lluvia'];
const pesos = {
  ocupacion_media: 0.35,
  adr: 0.15,
  pickup_7: 0.20,
  pct_dias_festivos: 0.15,
  pct_dias_vacaciones: 0.10,
  pct_dias_lluvia: 0.05
};

// Rangos min-max calculados incluyendo el periodo actual, para no distorsionar
// la normalización si el periodo actual es un extremo (ej. ocupación récord)
const todos = [...historico, actual];
const rangos = {};
features.forEach(f => {
  const valores = todos.map(r => r[f]).filter(v => v !== null && v !== undefined && !isNaN(v));
  rangos[f] = { min: Math.min(...valores), max: Math.max(...valores) };
});

function normalizar(valor, rango) {
  if (valor === null || valor === undefined || isNaN(valor)) return 0.5; // neutro si falta el dato
  if (rango.max === rango.min) return 0.5;
  return (valor - rango.min) / (rango.max - rango.min);
}

function distancia(a, h) {
  let suma = 0;
  features.forEach(f => {
    const na = normalizar(a[f], rangos[f]);
    const nh = normalizar(h[f], rangos[f]);
    suma += pesos[f] * Math.pow(na - nh, 2);
  });
  return Math.sqrt(suma);
}

const top3 = historico
  .map(h => ({ ...h, distancia: distancia(actual, h) }))
  .sort((a, b) => a.distancia - b.distancia)
  .slice(0, 3);

const contexto_historico = top3.length
  ? top3.map(p =>
      `Periodo ${p.fecha_inicio} a ${p.fecha_fin}: ocupación media ${p.ocupacion_media}%, ADR ${p.adr}€, RevPAR ${p.revpar}€, pickup_7 ${p.pickup_7}, festivos en ${Math.round(p.pct_dias_festivos * 100)}% de los días, vacaciones escolares en ${Math.round(p.pct_dias_vacaciones * 100)}% de los días, lluvia en ${p.pct_dias_lluvia != null ? Math.round(p.pct_dias_lluvia * 100) + '%' : 'sin datos'} (distancia de similitud: ${p.distancia.toFixed(3)}, menor = más parecido).`
    ).join('\n')
  : 'Sin periodos históricos disponibles para comparar.';

return [{
  json: {
    ...$('Normalizar Periodo Actual').first().json,
    contexto_historico,     // el texto para el LLM
    top3_periodos: top3     // el array crudo para la tabla del informe
  }
}];;

const total = $json.calculo_metricas.total;
const diario = $json.calculo_metricas.diario;

const dias_analizados = total.dias_analizados;
const ocupacion_media = total.ocupacion.prevista_media;
const adr = total.ingresos.adr_medio;
const revpar = total.ingresos.revpar_medio;
const pickup_7 = total.pickup_pace.pickup_7_medio;
const dias_festivos = total.contexto_externo.dias_festivos;
const dias_vacaciones_escolares = total.contexto_externo.dias_vacaciones_escolares;

const pct_dias_vacaciones = dias_analizados ? dias_vacaciones_escolares / dias_analizados : 0;
const pct_dias_festivos = dias_analizados ? dias_festivos / dias_analizados : 0;

// Clima: lo sacamos del contexto_externo.clima de cada día (ya lo trae 'Calcular Metricas')
const climas = diario.map(d => d.contexto_externo?.clima).filter(Boolean);
const diasConLluvia = climas.filter(c => c.precipitacion != null && c.precipitacion >= 1).length;
const diasBuenTiempo = climas.filter(c => c.precipitacion != null && c.precipitacion < 1 && c.temp_max > 20).length;
const media = arr => arr.length ? arr.reduce((a, b) => a + b, 0) / arr.length : null;
const tempMaxMedia = media(climas.map(c => c.temp_max).filter(v => v != null));
const precipTotal = climas.reduce((s, c) => s + (c.precipitacion ?? 0), 0);

const periodo_actual = {
  ocupacion_media: Number(ocupacion_media.toFixed(2)),
  adr: Number(adr.toFixed(2)),
  revpar: Number(revpar.toFixed(2)),
  pickup_7: pickup_7,
  dias_con_datos: dias_analizados,
  dias_vacaciones_escolares,
  dias_festivos,
  pct_dias_vacaciones: Number(pct_dias_vacaciones.toFixed(2)),
  pct_dias_festivos: Number(pct_dias_festivos.toFixed(2)),
  pct_dias_lluvia: climas.length ? Number((diasConLluvia / climas.length).toFixed(2)) : null,
  pct_dias_buen_tiempo: climas.length ? Number((diasBuenTiempo / climas.length).toFixed(2)) : null,
  temp_max_media: tempMaxMedia != null ? Number(tempMaxMedia.toFixed(1)) : null,
  precipitacion_total_mm: Number(precipTotal.toFixed(1))
};

return [{ json: { ...$json, periodo_actual } }];

// Recuperamos el objeto de métricas calculado antes de los agentes
const datosMetricas = $('Call \'Subflow - Calculo Metricas\'').first().json || {};
const motorAnalitico = datosMetricas.motor_analitico || datosMetricas.calculo_metricas || {};
const diario = motorAnalitico.diario || [];

if (!diario.length) {
  return [];
}

// Mapeamos los datos limpios a filas de tabla
return diario.map(d => ({
  json: {
    "Fecha": d.fecha,
    "Ocupacion_Actual_%": d.ocupacion?.actual ?? 0,
    "Ocupacion_Prevista_%": d.ocupacion?.prevista ?? 0,
    "ADR_EUR": d.ingresos?.adr ?? 0,
    "RevPAR_EUR": d.ingresos?.revpar ?? 0,
    "Pickup_7d": d.pickup_pace?.pickup_7 ?? 0,
    "Festivo": d.contexto_externo?.es_festivo ? "Sí" : "No",
    "Vacaciones": d.contexto_externo?.es_vacaciones_escolares ? "Sí" : "No"
  }
}));

const datosMetricas = $('Call \'Subflow - Calculo Metricas\'').first().json || {};
const motorAnalitico = datosMetricas.calculo_metricas || {};
const diario = motorAnalitico.diario || [];

if (!diario.length) return [];

return diario.map(d => ({
  json: {
    "Fecha": d.fecha,
    "Ocupacion_Prevista_%": d.ocupacion?.prevista ?? 0,
    "ADR_Actual_EUR": d.ingresos?.adr ?? 0,
    "ADR_Sugerido_EUR": d.pricing_dinamico?.adr_sugerido ?? null,
    "Ajuste_Pricing_%": d.pricing_dinamico?.ajuste_pct ?? null,
    "Limite_Alcanzado": d.pricing_dinamico?.limite_alcanzado ? "Sí" : "No",
    "RevPAR_EUR": d.ingresos?.revpar ?? 0,
    "Pickup_7d": d.pickup_pace?.pickup_7 ?? 0,
    "Ritmo_Pace": d.pickup_pace?.ritmo_pickup ?? null,
    "Riesgo_Ocupacion_Baja": d.riesgos?.ocupacion_baja ?? "Sin clasificar"
  }
}));

const datosMetricas = $('Call \'Subflow - Calculo Metricas\'').first().json || {};
const motorAnalitico = datosMetricas.calculo_metricas || {};
const diario = motorAnalitico.diario || [];

if (!diario.length) return [];

return diario.map(d => ({
  json: {
    "Fecha": d.fecha,
    "Ocupacion_Prevista_%": d.ocupacion?.prevista ?? 0,
