  }
}));

const texto = $input.item.json.output || $input.item.json.text || '';
const hoy = new Date().toISOString().split('T')[0];
const tareas = [];

function limpiarTexto(t) {
  return t.replace(/\*\*/g, '').replace(/^[-\*\d\.\s\[\]x]+/, '').trim();
}

// -----------------------------------------------------------------
// 1. EXTRAER CHECKLIST DE EJECUCIÓN (Tareas directas para el turno)
// -----------------------------------------------------------------
const matchChecklist = texto.match(/Check-list de Ejecución[\s\S]*?(?=(?:##|\n\n\n|$))/i);
if (matchChecklist) {
  const lineas = matchChecklist[0].split('\n');
  lineas.forEach(linea => {
    const l = linea.trim();
    // Captura líneas numeradas: "1. [PMS / CM]: ..." o viñetas
    if (/^(?:\d+[\.\)]|[-*])\s+/.test(l)) {
      const limpia = limpiarTexto(l);
      if (limpia.length > 8 && !limpia.toLowerCase().includes('lista numerada')) {
        tareas.push({
          json: {
            titulo: `✅ [Turno] ${limpia}`,
            vencimiento: `${hoy}T20:00:00.000Z`,
            notas: `Checklist diario de Revenue Management generado el ${hoy}.`
          }
        });
      }
    }
  });
}

// -----------------------------------------------------------------
// 2. EXTRAER ÓRDENES DE CARGA POR PERIODO Y CANAL (Tarifas y MinLOS)
// -----------------------------------------------------------------
const bloquesPeriodo = texto.split(/###\s+Periodo:/i);

// Omitimos el primer fragmento (cabecera antes del primer periodo)
for (let i = 1; i < bloquesPeriodo.length; i++) {
  const bloque = bloquesPeriodo[i];
  const nombrePeriodo = (bloque.split('\n')[0] || '').replace(/\*\*/g, '').trim();

  // Buscar órdenes específicas por canal
  const canales = [
    { key: 'Web Propia / Motor', etiqueta: 'Web' },
    { key: 'OTAs', etiqueta: 'OTAs' },
    { key: 'Canal Directo', etiqueta: 'Directo' }
  ];

  canales.forEach(canal => {
    const regexCanal = new RegExp(`${canal.key}[\\s\\S]*?(?=(?:- \\*\\*|###|##|$))`, 'i');
    const matchCanal = bloque.match(regexCanal);

    if (matchCanal) {
      const contenidoCanal = matchCanal[0];
      const tarifaMatch = contenidoCanal.match(/Tarifa [^:]*:\s*([^\n]+)/i);
      const restriccionMatch = contenidoCanal.match(/Restricci[oó]n:\s*([^\n]+)/i);

      const tarifa = tarifaMatch ? limpiarTexto(tarifaMatch[1]) : '';
      const restriccion = restriccionMatch ? limpiarTexto(restriccionMatch[1]) : '';

      if (tarifa || restriccion) {
        let detalle = [];
        if (tarifa) detalle.push(`Tarifa: ${tarifa}`);
        if (restriccion) detalle.push(`Restricción: ${restriccion}`);

        tareas.push({
          json: {
            titulo: `🏨 [${canal.etiqueta} | ${nombrePeriodo}] ${detalle.join(' · ')}`,
            vencimiento: `${hoy}T18:00:00.000Z`,
            notas: `Instrucción de carga para ${canal.key} en el periodo ${nombrePeriodo}.\n${contenidoCanal.trim()}`
          }
        });
      }
    }
  });
}

// -----------------------------------------------------------------
// 3. EXTRAER REGLAS DE YIELDING / TRIGGERS ACTIVOS
// -----------------------------------------------------------------
const matchYielding = texto.match(/Reglas Automatizadas de Yielding[\s\S]*?(?=(?:##|$))/i);
if (matchYielding) {
  const lineasYield = matchYielding[0].split('\n');
  let triggerActual = '';

  lineasYield.forEach(l => {
    const trimmed = l.trim();
    if (trimmed.toLowerCase().includes('trigger')) {
      triggerActual = limpiarTexto(trimmed);
    } else if (trimmed.toLowerCase().includes('acción inmediata:')) {
      const accion = limpiarTexto(trimmed.split(/acción inmediata:/i)[1]);
      if (accion) {
        tareas.push({
          json: {
            titulo: `⚡ [Alerta Yield] ${triggerActual ? triggerActual + ': ' : ''}${accion}`,
            vencimiento: `${hoy}T21:00:00.000Z`,
            notas: `Regla de yielding a supervisar en el PMS durante el turno de hoy (${hoy}).`
          }
        });
      }
    }
  });
}

// Si por alguna razón no extrajo nada, devuelve aviso
return tareas.length ? tareas : [{ json: { titulo: "Revisar informe de Revenue diario", vencimiento: `${hoy}T20:00:00.000Z`, notas: "No se pudieron desglosar las tareas automáticamente." } }];

const hoy = new Date();
