const fechaInicio = hoy.toISOString().split('T')[0];

function assertField(val, errorMsg) {
  if (val === undefined || val === null || val === '' || (typeof val === 'number' && isNaN(val))) {
    throw new Error('[VALIDACION CONFIG]: ' + errorMsg);
  }
  return val;
}

const hotelConfig = $input.item.json.hotelConfig || $('Construir Contexto Hotel').first()?.json?.hotelConfig;

